sys_script_client.script:
function onLoad() {
    var patientId = g_form.getUniqueValue(); // sys_id of current patient record

    var ga = new GlideAjax('PatientAjaxHelper');
    ga.addParam('sysparm_name', 'getPatientDetails');
    ga.addParam('sysparm_patient_id', patientId);

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            g_form.addInfoMessage(data.error);
        } else {
            var msg = 'Welcome, ' + data.name +
                      ' | Gender: ' + data.gender;
            g_form.addInfoMessage(msg);
        }
    });
}
